import numpy as np

PERIODS_PER_YEAR = 252

def sharpe_ratio(returns, risk_free=0.0):
    excess = np.asarray(returns) - risk_free
    if excess.std(ddof=0) == 0:
        return 0.0
    return (excess.mean() / excess.std(ddof=0)) * np.sqrt(PERIODS_PER_YEAR)

def sortino_ratio(returns, mar=0.0):
    returns = np.asarray(returns)
    downside = np.minimum(returns - mar, 0.0)
    downside_deviation = np.sqrt(np.mean(downside ** 2))
    if downside_deviation == 0:
        return 0.0
    return ((returns.mean() - mar) / downside_deviation) * np.sqrt(PERIODS_PER_YEAR)

def max_drawdown(equity_curve):
    equity_curve = np.asarray(equity_curve)
    running_peak = np.maximum.accumulate(equity_curve)
    return ((running_peak - equity_curve) / running_peak).max()

def value_at_risk(returns, confidence=0.95):
    return -np.percentile(np.asarray(returns), 100 * (1 - confidence))

def conditional_value_at_risk(returns, confidence=0.95):
    returns = np.asarray(returns)
    threshold = np.percentile(returns, 100 * (1 - confidence))
    return -returns[returns <= threshold].mean()
